local D,H,S=game:GetService("DataStoreService"),game:GetService("HttpService"),game:GetService("StudioService");local NOM="Joueurs_v2";local c="joueur_"..S:GetUserId();local st=D:GetDataStore(NOM);local o=Instance.new("DataStoreGetOptions");o.UseCache=false;local ok,d,i=pcall(function() return st:GetAsync(c,o) end);if not ok then warn("Lecture impossible : "..tostring(d)) elseif d==nil then warn("Aucune sauvegarde pour "..c.." dans "..NOM) else local t=H:JSONEncode(d);print("===== DEBUT "..NOM.." / "..c.." (version Roblox "..tostring(i and i.Version)..") =====");for k=1,#t,1500 do print(string.sub(t,k,k+1499)) end;print("===== FIN ("..#t.." caracteres, recolle les morceaux sans espace) =====") end;local ok2,p=pcall(function() return st:ListVersionsAsync(c,Enum.SortDirection.Descending,nil,nil,10) end);if ok2 then for _,v in p:GetCurrentPage() do print("version gardee : "..v.Version.." du "..DateTime.fromUnixTimestampMillis(v.CreatedTime):FormatLocalTime("LLL","fr-fr")) end else warn("Liste des versions impossible : "..tostring(p)) end
